func TestEnsureFreshRefreshesMissingAndStaleResources(t *testing.T) {
	now := time.Date(2026, 5, 9, 12, 0, 0, 0, time.UTC)
	states := map[string]FreshnessState{
		"fresh": {LastSynced: now.Add(-time.Hour), Count: 3},
		"stale": {LastSynced: now.Add(-48 * time.Hour), Count: 4},
		"empty": {LastSynced: now.Add(-time.Hour), Count: 0},
	}
	var refreshed []string

	report, err := EnsureFresh(context.Background(), FreshnessOptions{
		Resources:  []string{"fresh", "stale", "empty", "missing"},
		StaleAfter: 24 * time.Hour,
		Now:        func() time.Time { return now },
		State: func(_ context.Context, resource string) (FreshnessState, error) {
			state, ok := states[resource]
			if !ok {
				return FreshnessState{}, errors.New("not synced")
			}
			return state, nil
		},
		Refresh: func(_ context.Context, resource string) error {
			refreshed = append(refreshed, resource)
			return nil
		},
	})
	if err != nil {
		t.Fatalf("EnsureFresh: %v", err)
	}

	wantRefreshed := []string{"stale", "empty", "missing"}
	if !reflect.DeepEqual(refreshed, wantRefreshed) {
		t.Fatalf("refreshed = %#v, want %#v", refreshed, wantRefreshed)
	}
	if report.RefreshedCount != 3 {
		t.Fatalf("RefreshedCount = %d, want 3", report.RefreshedCount)
	}
	if report.StaleCount != 3 {
		t.Fatalf("StaleCount = %d, want 3", report.StaleCount)
	}
	if report.MissingCount != 2 {
		t.Fatalf("MissingCount = %d, want 2", report.MissingCount)
	}
}

func TestEnsureFreshReturnsContextCancellation(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()

	_, err := EnsureFresh(ctx, FreshnessOptions{
		Resources: []string{"products"},
		State: func(_ context.Context, _ string) (FreshnessState, error) {
			return FreshnessState{}, nil
		},
	})
	if !errors.Is(err, context.Canceled) {
		t.Fatalf("err = %v, want context.Canceled", err)
	}
}
